// ============================================================
// HEALTH MONITOR - Analyze Failed Executions
// ============================================================
// Scans recent failed executions, identifies patterns,
// and determines which ones to auto-retry.
// ============================================================

const response = $input.first().json;
const executions = response.data || response.results || response || [];

if (!Array.isArray(executions) || executions.length === 0) {
  return [{ json: { _no_failures: true, summary: 'No recent failures found. All systems healthy.' } }];
}

// Analyze each failed execution
const now = new Date();
const fifteenMinAgo = new Date(now.getTime() - 15 * 60 * 1000);
const oneHourAgo = new Date(now.getTime() - 60 * 60 * 1000);

// Only look at failures from the last hour
const recentFailures = executions.filter(ex => {
  const finishedAt = new Date(ex.stoppedAt || ex.startedAt);
  return finishedAt >= oneHourAgo;
});

if (recentFailures.length === 0) {
  return [{ json: { _no_failures: true, summary: 'No failures in the last hour. All systems healthy.' } }];
}

// Group failures by workflow
const failuresByWorkflow = {};
for (const ex of recentFailures) {
  const wfName = ex.workflowData?.name || ex.workflowId || 'Unknown';
  if (!failuresByWorkflow[wfName]) {
    failuresByWorkflow[wfName] = [];
  }
  failuresByWorkflow[wfName].push(ex);
}

// Build health report
const healthReport = [];
let totalFailures = recentFailures.length;
let criticalWorkflows = 0;

for (const [wfName, failures] of Object.entries(failuresByWorkflow)) {
  const count = failures.length;
  const isCritical = count >= 3; // 3+ failures = critical
  if (isCritical) criticalWorkflows++;

  // Get the most recent error
  const latest = failures[0];
  const errorMsg = latest.data?.resultData?.error?.message || 'Unknown error';

  healthReport.push({
    workflow_name: wfName,
    failure_count: count,
    status: isCritical ? 'CRITICAL' : count >= 2 ? 'WARNING' : 'ALERT',
    latest_error: errorMsg.substring(0, 200),
    latest_execution_id: latest.id
  });
}

// Sort by failure count descending
healthReport.sort((a, b) => b.failure_count - a.failure_count);

// Build summary Slack message
let lines = [];
lines.push(':hospital: *n8n Health Monitor Report*');
lines.push(`_Scanned: ${new Date().toLocaleString('en-US', {timeZone: 'America/New_York'})} ET_`);
lines.push('');
lines.push(`Total failures (last hour): *${totalFailures}*`);
lines.push(`Critical workflows: *${criticalWorkflows}*`);
lines.push('');

for (const item of healthReport) {
  const emoji = item.status === 'CRITICAL' ? ':red_circle:' : item.status === 'WARNING' ? ':large_orange_circle:' : ':large_yellow_circle:';
  lines.push(`${emoji} *${item.workflow_name}* — ${item.failure_count} failure(s)`);
  lines.push(`   Latest: \`${item.latest_error}\``);
  lines.push('');
}

lines.push('---');
lines.push('_Check Google Sheets error log for full details._');

return [{
  json: {
    _no_failures: false,
    total_failures: totalFailures,
    critical_workflows: criticalWorkflows,
    health_report: healthReport,
    _slack_summary: lines.join('\n'),
    timestamp: new Date().toISOString()
  }
}];
